      with (l := [SWin 2; SCycL 2 0; SWin 1; SWinL 3]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0RB_0LC0RA_0LD1LC_1RA1LC
      with (l := [SWin 2; SCycL 2 0; SWin 1]).
