Lemma fire_1RB0RB_0LC0RA_1LD0RB_1RA1LC : forall t, ~ In t pins_1RB0RB_0LC0RA_1LD0RB_1RA1LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
