(** ** The lap *)

Lemma lap_1RB0RB_0LC0RB_1LD1LB_1RA1LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0RB_0LC0RB_1LD1LB_1RA1LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0RB_0LC0RB_1LD1LB_1RA1LC B0_1RB0RB_0LC0RB_1LD1LB_1RA1LC B1_1RB0RB_0LC0RB_1LD1LB_1RA1LC 4 8 p j' [] []).
    + exact run_ovf_1RB0RB_0LC0RB_1LD1LB_1RA1LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0RB_0LC0RB_1LD1LB_1RA1LC p j' E).
    + exact (geo_1RB0RB_0LC0RB_1LD1LB_1RA1LC p j' E).
    + lia.
Qed.

