  split; [lia|]. split; [| exact (gen_1RB0RB_0LC1RA_1RB1LD_1RA1LC v i q0 E)].
  rewrite (gsn_1RB0RB_0LC1RA_1RB1LD_1RA1LC v i q0 E).
  exact (srun_sound tm false true chn_1RB0RB_0LC1RA_1RB1LD_1RA1LC AI0_1RB0RB_0LC1RA_1RB1LD_1RA1LC AI1_1RB0RB_0LC1RA_1RB1LD_1RA1LC 4 8
