  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DL StB
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StA
  | StC, S0 => mk S0 DL StD | StC, S1 => mk S0 DR StC
  | StD, S0 => mk S1 DL StA | StD, S1 => mk S0 DL StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0RB_1LC1RA_0RD0LC_1RA0RD : list Instr := [(StA, S1); (StD, S1)].
Definition tmw_1RB0RB_1LC1RA_0RD0LC_1RA0RD : TM := tm_wrap_trs tmm_1RB0RB_1LC1RA_0RD0LC_1RA0RD pins_1RB0RB_1LC1RA_0RD0LC_1RA0RD.
