Lemma fire_1RB0RB_1LC1RA_0RD0LC_1RA1LA : forall t, ~ In t pins_1RB0RB_1LC1RA_0RD0LC_1RA1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
