    apply (fireo_1RB0RB_1LC1RA_0RD0LC_1RA1LA [SWin 2; SCycL 2 0; SWin 1; SWinL 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
