  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DR StB
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StA
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S0 DL StC
  | StD, S0 => mk S0 DR StA | StD, S1 => mk S1 DR StC end.

(** Its mirror 1LB0LB_1RC1LA_1RD0RC_0LA1LC: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0RB_1LC1RA_1LD0LC_0RA1RC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DL StB
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StA
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S0 DR StC
  | StD, S0 => mk S0 DL StA | StD, S1 => mk S1 DL StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0RB_1LC1RA_1LD0LC_0RA1RC : list Instr := [(StD, S1)].
Definition tmw_1RB0RB_1LC1RA_1LD0LC_0RA1RC : TM := tm_wrap_trs tmm_1RB0RB_1LC1RA_1LD0LC_0RA1RC pins_1RB0RB_1LC1RA_1LD0LC_0RA1RC.
