Lemma geo_1RB0RB_1LC1RA_1LD0LC_0RA1RC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RB_1LC1RA_1LD0LC_0RA1RC) = lift (Cc (Pos.succ p)).
