(** ** The lap *)

Lemma lap_1RB0RB_1LC1RA_1LD0LC_0RA1RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
