  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0RB_1LC1RA_1LD0LC_0RA1RC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0RB_1LC1RA_1LD0LC_0RA1RC B0_1RB0RB_1LC1RA_1LD0LC_0RA1RC B1_1RB0RB_1LC1RA_1LD0LC_0RA1RC 4 8 p j' [] []).
    + exact run_ovf_1RB0RB_1LC1RA_1LD0LC_0RA1RC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0RB_1LC1RA_1LD0LC_0RA1RC p j' E).
    + exact (geo_1RB0RB_1LC1RA_1LD0LC_0RA1RC p j' E).
    + lia.
Qed.

