    apply (lap_of_run tm Cc true true cho_1RB0RB_1LC1RD_0RB0LC_1RA0LD B0_1RB0RB_1LC1RD_0RB0LC_1RA0LD B1_1RB0RB_1LC1RD_0RB0LC_1RA0LD 6 8 p j' [] []).
    + exact run_ovf_1RB0RB_1LC1RD_0RB0LC_1RA0LD.
