  exists (6 * j + 6), (cden (Ap_Alph_000_010_01 q0 ++ [S0]) [] j A1_1RB0RB_1LC1RD_0RD0LC_1RA0LA).
  split; [lia|]. split; [| exact (gei_1RB0RB_1LC1RD_0RD0LC_1RA0LA p j q0 E)].
  rewrite (gsi_1RB0RB_1LC1RD_0RD0LC_1RA0LA p j q0 E).
