Lemma geo_1RB0RB_1LC1RD_0RD0LC_1RA0LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RB_1LC1RD_0RD0LC_1RA0LA) = lift (Cc (Pos.succ p)).
