(** ** The lap *)

Lemma lap_1RB0RB_1LC1RD_0RD0LC_1RA0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0RB_1LC1RD_0RD0LC_1RA0LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0RB_1LC1RD_0RD0LC_1RA0LA B0_1RB0RB_1LC1RD_0RD0LC_1RA0LA B1_1RB0RB_1LC1RD_0RD0LC_1RA0LA 6 12 p j' [] []).
    + exact run_ovf_1RB0RB_1LC1RD_0RD0LC_1RA0LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0RB_1LC1RD_0RD0LC_1RA0LA p j' E).
    + exact (geo_1RB0RB_1LC1RD_0RD0LC_1RA0LA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB0RB_1LC1RD_0RD0LC_1RA0LA : stepn tmm_1RB0RB_1LC1RD_0RD0LC_1RA0LA 14 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_1RB0RB_1LC1RD_0RD0LC_1RA0LA 14 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB0RB_1LC1RD_0RD0LC_1RA0LA 14 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

