      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* A1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0RB_1LC1RD_0RD0LC_1RA1RC
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 3; SWinL 2]).
