      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0RB_1LC1RD_0RD0LC_1RA1RC
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0RB_1LC1RD_0RD0LC_1RA1RC
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 3; SWinL 3]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0RB_1LC1RD_0RD0LC_1RA1RC
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D1: pinned *)
