(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB0RB_1LC1RD_0RD0LC_1RA1RD : sconf := mkC StC (mkS [] [S0;S0;S0] 1 0 [S0;S0;S1;S1;S0]) S0 (mkS [S1] [] 0 0 []).
Definition chb_1RB0RB_1LC1RD_0RD0LC_1RA1RD : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SCycR 3; SWin 1; SUnrotL 1].

Lemma run_boot_1RB0RB_1LC1RD_0RD0LC_1RA1RD : srun tm true true chb_1RB0RB_1LC1RD_0RD0LC_1RA1RD B0_1RB0RB_1LC1RD_0RD0LC_1RA1RD = Some (BB1_1RB0RB_1LC1RD_0RD0LC_1RA1RD, 6, 6).
