(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB0RB_1LC1RD_0RD0LC_1RA1RD : sconf := mkC StC (mkS [] [S0;S0;S1] 1 0 [S0;S0;S1;S1]) S0 (mkS [S1] [] 0 0 []).
Definition che_1RB0RB_1LC1RD_0RD0LC_1RA1RD : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 3; SWinL 9; SCycR 3; SWin 1; SRotL 2; SFoldL 1].

Lemma run_exit_1RB0RB_1LC1RD_0RD0LC_1RA1RD : srun tm true true che_1RB0RB_1LC1RD_0RD0LC_1RA1RD BE0_1RB0RB_1LC1RD_0RD0LC_1RA1RD = Some (B1_1RB0RB_1LC1RD_0RD0LC_1RA1RD, 6, 14).
